\label{thm:Hpath}
    Let $K_{V_1,V_2,...V_m}$ be the complete multipartite graph with partite sets $V_1,V_2,...,V_m$. The number of directed Hamiltonian paths in $K_{V_1,V_2,...V_m}$ is
    \begin{align}\label{Thm2.2}
        H^P(K_{V_1,V_2,...V_m}) = e_{(|V_1|,|V_2|,...,|V_m|)}\prod_{i=1}^m|V_i|!,
    \end{align}

    \noindent where $e_n$ is given in Equation $(\ref{eq:e})$.

The formula in Lemma \ref{lem:E} can also be written in the suggestive manner
\begin{equation*}
\tilde E_n = {|n| \choose n}  \frac{\left(\sum_{j=1}^m n_j\right)^2 - \sum_{j=1}^m n_j^2}{\left(\sum_{j=1}^m n_j\right)^2 - \sum_{j=1}^m n_j}\ .
\end{equation*}

\label{thm:Ee}
Let $m \in \mathbb N$, $m \ge 2$, and $n\in\mathbb N^m$. Then
\begin{equation*}
\tilde e_n = \sum_{0_m \le k \le n - 1_m} (-1)^{|k|} {n - 1_m \choose k} \tilde E_{n-k}.
\end{equation*}

The formula in Theorem \ref{thm:cyc} is intriguing in that the fraction on the right hand side does
not in general produce an integer by itself; e.g. for $|V_1| = 3$, $|V_2| = |V_3| = 2$
we obtain by Theorem \ref{thm:Ee}
\begin{equation*}
H^C(K_{V_1, V_2, V_3}) =
\tilde e_{(3,2,2)}\,\frac{3!\,2!\,2!}{7} = 28\,\frac{24}{7} = 96.
\end{equation*}
The total result is of course an integer (in fact an even integer since every directed Hamiltonian cycle is paired with the same cycle in opposite direction), but there is a subtle cancellation
between the 7 in the denominator and the value of $\tilde e_{(3,2,2)}$.

By the explicit formulae found in Lemma \ref{lem:E} and Theorem \ref{thm:Ee},
the count of directed Hamiltonian cycles in $K_{V_1, V_2, \dots, V_m}$ takes the full form,
written without multi-index notation for easier comparison,
\begin{align*}
\frac{\prod_{j=1}^m |V_j|!}{|V|} &\sum_{k_1=0}^{|V_1|-1} \sum_{k_2=0}^{|V_2|-1} \cdots \sum_{k_m = 0}^{|V_m|-1} (-1)^{\sum_{j=1}^m k_j} {|V_1| - 1 \choose k_1}
{|V_2| - 1 \choose k_2} \cdots {|V_m| - 1 \choose k_m}
\\
&\qquad\times
{\sum_{j=1}^m (|V_j| - k_j)
\choose |V_1|-k_1, \dots, |V_m|-k_m}
\left(1 - \frac{\sum_{j=1}^m (|V_j|-k_j)(|V_j|-k_j-1)}{(|V| - \sum_{j=1}^m k_j)(|V|-1 - \sum_{j=1}^m k_j)}\right),
\end{align*}
which is similar to, but not quite identical with the formula in \cite{MSmirnov}.
